<textarea id="partitionCodeCode">function PARTITION(A, p, r) {
  const x = pivot(r);
  let i = p - 1;
  setI(i);

  for (let j = p; j &lt;= r - 1; j++) {
    setJ(j);
    note('Top of loop: left is &lt;= x, middle is &gt; x, right is unrestricted.');

    if (compare(j, x)) {
      i = i + 1;
      swap(i, j);
      setI(i);
      note('A[j] &lt;= x, so it is swapped into the &lt;= x region.');
    } else {
      note('A[j] &gt; x, so it stays in the &gt; x region.');
    }

    setJ(j + 1);
    note('After the iteration, j advances and the invariant is restored.');
  }

  swap(i + 1, r);
  setI(i + 1);
  note('Place the pivot between the &lt;= x and &gt; x regions.');
  return i + 1;
}</textarea>
