var buggyCode = "function PARTITION(A, p, r) {\n  const x = pivot(r);\n  let i = p - 1;\n  setI(i);\n\n  for (let j = p; j <= r - 1; j++) {\n    setJ(j);\n    if (compare(j, x)) {\n      swap(i, j);\n      setI(i);\n      i = i + 1;\n      note('Bug: swaps before advancing i, so the new <= x item goes to the wrong place.');\n    }\n    setJ(j + 1);\n  }\n\n  swap(i + 1, r);\n  setI(i + 1);\n  return i + 1;\n}";
var starterCode = "function PARTITION(A, p, r) {\n  const x = pivot(r);\n  let i = p - 1;\n  setI(i);\n\n  for (let j = p; j <= r - 1; j++) {\n    setJ(j);\n    // TODO: compare A[j] with x.\n    // If it is <= x, advance i and swap it left.\n  }\n\n  // TODO: put the pivot in its final position.\n  return i + 1;\n}";

var scene = draw.group();
var frames = [];
var frameIndex = -1;
var playTimer = null;
var violationIndices = [];
var lastRunHadError = false;
var demoIndex = 0;
var checkpoint = 'top of iteration';
var currentSmallCase = true;

var demoSteps = [
  {
    title: 'Read the invariant',
    narration: 'At the top of the loop, everything up to i is already known to be ≤ x, everything from i+1 through j-1 is known to be > x, and everything from j through r-1 has not yet been examined.',
    checkpoint: 'top of iteration',
    small: true
  },
  {
    title: 'When A[j] is small enough',
    narration: 'If the current element is ≤ x, it belongs in the left region. PARTITION first expands that region by one position, then swaps A[j] into it.',
    checkpoint: 'after <= x branch',
    small: true
  },
  {
    title: 'When A[j] is too large',
    narration: 'If the current element is > x, it already belongs in the middle region. No swap is needed; advancing j simply grows the > x region by one cell.',
