function parseArrayInput() {
  var src = document.getElementById('partitionCodeInput').value.trim();
  if (!src) throw new Error('Enter at least one number.');
  var vals = src.split(/[,\s]+/).filter(Boolean).map(function (s) { return Number(s); });
  if (!vals.length || vals.some(function (v) { return !isFinite(v); })) throw new Error('Array input must be a comma-separated list of numbers.');
  if (vals.length < 2) throw new Error('Need at least two elements so A[r] can be a pivot.');
  return vals;
}

function loadPartitionSample(which) {
  document.getElementById('partitionCodeCode').value = which === 'buggy' ? buggyCode : (which === 'starter' ? starterCode : sampleCode);
}

function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = '▶';
}

function withTip(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
  return el;
}

function addHaloText(g, txt, x, y, size, anchor, italic) {
  return g.text(txt).font({
    family: 'Times New Roman, serif',
    size: size,
    anchor: anchor || 'middle',
    style: italic ? 'italic' : 'normal'
  }).attr({
    x: x,
    y: y,
    'dominant-baseline': 'middle',
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 5,
    'stroke-linejoin': 'round',
    fill: '#000'
  });
}

function bracePath(x1, x2, y) {
  var mid = (x1 + x2) / 2;
  var c = Math.min(48, Math.max(18, (x2 - x1) / 6));
  return 'M ' + x1 + ' ' + y +
    ' C ' + x1 + ' ' + (y + 16) + ' ' + (mid - c) + ' ' + (y + 9) + ' ' + mid + ' ' + (y + 27) +
    ' C ' + (mid + c) + ' ' + (y + 9) + ' ' + x2 + ' ' + (y + 16) + ' ' + x2 + ' ' + y;
}

function drawBrace(g, x1, x2, y, label, tip) {
  if (x2 <= x1 + 14) return;
  var b = g.path(bracePath(x1, x2, y)).fill('none').stroke({ color: '#000', width: 2.2, linecap: 'round' });
  withTip(b, tip, label, tip);
  addHaloText(g, label, (x1 + x2) / 2, y + 55, label === 'unrestricted' ? 38 : 42, 'middle', label !== 'unrestricted');
}

function frameFromDemo() {
  if (checkpoint === 'after <= x branch') {
    return {
      kind: 'swap',
      state: { A: [2, 1, 3, 8, 7, 5, 6, 4], p: 0, r: 7, i: 2, j: 4, x: 4 },
      indices: [2, 4],
      message: 'A[j] ≤ x: expand the left region and swap the small item into it.'
    };
  }
  if (checkpoint === 'after > x branch') {
    return {
      kind: 'advance',
      state: { A: [2, 1, 3, 8, 7, 5, 6, 4], p: 0, r: 7, i: 2, j: 5, x: 4 },
      indices: [4],
      message: 'A[j] > x: no swap is needed; j advances, so the middle region grows.'
    };
  }
  if (checkpoint === 'after final pivot swap') {
    return {
      kind: 'swap',
      state: { A: [2, 1, 3, 4, 7, 5, 6, 8], p: 0, r: 7, i: 3, j: 7, x: 4, returnValue: 3, finalPivot: true },
      indices: [3, 7],
      message: 'Final pivot swap: x moves to i+1, separating the two finished sides.'
    };
  }
  if (currentSmallCase) {
    return {
      kind: 'compare',
      state: { A: [2, 1, 7, 8, 3, 5, 6, 4], p: 0, r: 7, i: 1, j: 4, x: 4 },
      indices: [4, 7],
      message: 'Top of loop: A[j]=3 is still unrestricted until compare classifies it.'
    };
  }
  return {
    kind: 'compare',
    state: { A: [2, 1, 3, 8, 7, 5, 6, 4], p: 0, r: 7, i: 2, j: 4, x: 4 },
    indices: [4, 7],
    message: 'Top of loop: A[j]=7 is too large, so it will become part of the > x region.'
  };
}

function defaultAbstractFrame() {
  return {
    kind: 'static',
    state: { A: null, n: 16, p: 0, r: 15, i: 3, j: 10, x: 'x' },
    indices: [],
    message: 'A[p..i] ≤ x, A[i+1..j−1] > x, A[j..r−1] unrestricted, and A[r] stores x.'
  };
}

function renderFrame(frame, bad) {
  scene.clear();
  bad = bad || [];
  var s = frame && frame.state ? frame.state : defaultAbstractFrame().state;
  var A = Array.isArray(s.A) ? s.A.slice() : null;
  var n = A ? A.length : (s.n || 16);
  var p = s.p == null ? 0 : s.p;
  var r = s.r == null ? n - 1 : s.r;
  var i = s.i == null ? 3 : s.i;
  var j = s.j == null ? 10 : s.j;
  var finalPivot = !!s.finalPivot;
  var q = finalPivot ? i : null;

  var left = 42, top = 95, w = 916, h = 60;
  var cw = w / n;
  var pale = '#e6e6e6', dark = '#a6a6a6';

  var bg = scene.rect(w, h).move(left, top).fill('#fff').stroke({ color: '#000', width: 2 });
  withTip(bg, 'The array segment A[p..r] being partitioned.', 'Subarray A[p..r]', 'PARTITION only rearranges this subarray around the pivot. It does not fully sort the subarray.');

  for (var k = 0; k < n; k++) {
    var fill = '#fff';
    if (finalPivot) {
      if (k < q) fill = pale;
      else if (k > q) fill = dark;
    } else {
      if (k <= i) fill = pale;
      else if (k < j && k < r) fill = dark;
      else fill = '#fff';
      if (k === r) fill = '#fff';
    }

    var cell = scene.rect(cw, h).move(left + k * cw, top).fill(fill).stroke({ color: '#000', width: 1.8 });
    var regionTip = 'Unexamined or pivot cell';
    if (finalPivot && k < q) regionTip = 'Final left side: every value here is ≤ x.';
    else if (finalPivot && k === q) regionTip = 'Pivot x is now in its final partition position.';
    else if (finalPivot && k > q) regionTip = 'Final right side: every value here is > x.';
    else if (k <= i) regionTip = 'Known ≤ x region A[p..i].';
    else if (k < j && k < r) regionTip = 'Known > x region A[i+1..j−1].';
    else if (k >= j && k < r) regionTip = 'Unrestricted region A[j..r−1]: not examined yet.';
    else if (k === r) regionTip = 'Pivot cell A[r], holding x.';
    withTip(cell, regionTip, 'Partition invariant region', regionTip);

    if (A) {
      addHaloText(scene, String(A[k]), left + k * cw + cw / 2, top + h / 2 + 1, 24, 'middle', false);
    }
  }

  if (!A) {
    addHaloText(scene, 'x', left + r * cw + cw / 2, top + h / 2 + 3, 44, 'middle', true);
  } else if (!finalPivot) {
    addHaloText(scene, 'x=' + String(s.x), left + r * cw + cw / 2, top + h + 26, 19, 'middle', false);
  } else {
    addHaloText(scene, 'x', left + q * cw + cw / 2, top + h + 25, 20, 'middle', true);
  }

  for (var grid = 1; grid < n; grid++) {
    scene.line(left + grid * cw, top, left + grid * cw, top + h).stroke({ color: '#000', width: 1.8 });
  }

  function marker(boundary, label, labelDx, tip) {
    var x = left + boundary * cw;
    var m = scene.rect(13, h + 12).move(x - 6.5, top - 6).fill('#000');
    withTip(m, tip, label, tip);
    addHaloText(scene, label, x + (labelDx || 0), top - 37, 42, 'middle', true);
  }

  addHaloText(scene, 'p', left + cw * 0.45, top - 37, 42, 'middle', true);
  if (finalPivot) {
    marker(q + 1, 'i', -28, 'Boundary after the final ≤ x region.');
    marker(Math.min(r, q + 1), 'j', 24, 'At the end of scanning, j has reached the pivot side.');
    marker(r, 'r', 28, 'Original last index r: this cell participated in the final pivot swap.');
  } else {
    marker(Math.max(0, i + 1), 'i', -32, 'i marks the last cell known to contain a value ≤ x.');
    marker(Math.min(r, j), 'j', 28, 'j marks the first unrestricted cell; it discovers the next element.');
    marker(r, 'r', 28, 'r is the pivot position before the final swap.');
  }

  var idxs = (frame && frame.indices) ? frame.indices.slice() : [];
  idxs = idxs.concat(bad || []);
  var seen = {};
  idxs.forEach(function (idx) {
    if (idx == null || idx < 0 || idx >= n || seen[idx]) return;
    seen[idx] = true;
    var color = bad.indexOf(idx) >= 0 ? '#d62728' : (frame.kind === 'swap' ? '#ff9800' : '#2b78e4');
    scene.rect(cw - 8, h - 8).move(left + idx * cw + 4, top + 4)
      .fill('none').stroke({ color: color, width: 4 }).radius(3);
  });

  if (frame && frame.kind === 'swap' && idxs.length >= 2) {
    var a = idxs[0], b = idxs[1];
    if (a >= 0 && b >= 0 && a < n && b < n) {
      var x1 = left + a * cw + cw / 2, x2 = left + b * cw + cw / 2, y = top - 18;
      scene.path('M ' + x1 + ' ' + y + ' C ' + x1 + ' ' + (y - 40) + ' ' + x2 + ' ' + (y - 40) + ' ' + x2 + ' ' + y)
        .fill('none').stroke({ color: '#ff9800', width: 3, linecap: 'round' });
      scene.circle(8).center(x1, y).fill('#ff9800');
      scene.circle(8).center(x2, y).fill('#ff9800');
    }
  }

  var leftEnd = left + Math.max(0, i + 1) * cw;
  var midEnd = left + Math.min(j, r) * cw;
  if (finalPivot) {
    drawBrace(scene, left, left + q * cw, top + h + 26, '≤ x', 'All values left of the pivot are ≤ x.');
    drawBrace(scene, left + (q + 1) * cw, left + (r + 1) * cw, top + h + 26, '> x', 'All values right of the pivot are > x.');
  } else {
    drawBrace(scene, left, leftEnd, top + h + 26, '≤ x', 'A[p..i] is the region already known to be ≤ x.');
    drawBrace(scene, leftEnd, midEnd, top + h + 26, '> x', 'A[i+1..j−1] is known to be > x.');
    drawBrace(scene, midEnd, left + r * cw, top + h + 26, 'unrestricted', 'A[j..r−1] has not been examined yet.');
  }

  var ann = frame && frame.message ? frame.message : 'Partition invariant';
  scene.rect(780, 28).move(110, 22).fill({ color: '#fff', opacity: 0.78 }).stroke({ color: '#ddd', width: 1 });
  scene.text(ann).font({ family: 'sans-serif', size: 15, anchor: 'middle' })
    .attr({ x: 500, y: 41, 'dominant-baseline': 'middle', fill: '#222' });

  if (A) {
    scene.text('Invariant: A[p..i] ≤ x  |  A[i+1..j−1] > x  |  A[j..r−1] unrestricted')
      .font({ family: 'sans-serif', size: 14, anchor: 'middle' })
      .attr({ x: 500, y: 322, 'dominant-baseline': 'middle', fill: '#333' });
  }
}

function updateCounterAndCaption() {
  var counter = document.getElementById('frameCounter');
  var cap = document.getElementById('frameCaption');
  if (!frames.length || frameIndex < 0) {
    counter.textContent = '0 of 0';
    cap.textContent = 'Use Run and trace, or step through the invariant demo below.';
    return;
  }
  counter.textContent = (frameIndex + 1) + ' of ' + frames.length;
  cap.textContent = frames[frameIndex].message || frames[frameIndex].kind;
  var log = frames.slice(Math.max(0, frameIndex - 8), frameIndex + 1).map(function (f, n) {
    return (Math.max(0, frameIndex - 8) + n + 1) + '. ' + (f.message || f.kind);
  }).join('\n');
  document.getElementById('partitionLog').textContent = log;
}

function showFrame(idx) {
  if (!frames.length) return;
  frameIndex = Math.max(0, Math.min(frames.length - 1, idx));
  var bad = frameIndex === frames.length - 1 ? violationIndices : [];
  renderFrame(frames[frameIndex], bad);
  updateCounterAndCaption();
}

function firstFrame() { stopPlay(); showFrame(0); }
function prevFrame() { stopPlay(); showFrame(frameIndex - 1); }
function nextFrame() {
  if (!frames.length) return;
  if (frameIndex >= frames.length - 1) { stopPlay(); return; }
  showFrame(frameIndex + 1);
}
function togglePlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = '❚❚';
  playTimer = setInterval(function () {
    if (frameIndex >= frames.length - 1) stopPlay();
    else showFrame(frameIndex + 1);
  }, 650 / Number(document.getElementById('partitionSpeedInput').value || 1));
}

function checkSuccess(finalFrame, original) {
  violationIndices = [];
  if (!finalFrame || !finalFrame.state || lastRunHadError) return false;
  var A = finalFrame.state.A || [];
  var q = Number(finalFrame.state.returnValue);
  var x = original[original.length - 1];
  var ok = Number.isInteger(q) && q >= 0 && q < A.length && A[q] === x;
  if (!ok && Number.isInteger(q) && q >= 0 && q < A.length) violationIndices.push(q);
  if (!Number.isInteger(q) || q < 0 || q >= A.length) {
    for (var z = 0; z < A.length; z++) violationIndices.push(z);
    return false;
  }
  for (var a = 0; a < q; a++) if (!(A[a] <= x)) { ok = false; violationIndices.push(a); }
  for (var b = q + 1; b < A.length; b++) if (!(A[b] > x)) { ok = false; violationIndices.push(b); }
  return ok;
}

function runPartitionCode() {
  stopPlay();
  var status = document.getElementById('partitionStatus');
  var runBtn = document.getElementById('partitionRunBtn');
  var inputArray;
  try {
    inputArray = parseArrayInput();
  } catch (e) {
    status.textContent = 'error: ' + e.message;
    return;
  }

  status.textContent = 'running…';
  runBtn.disabled = true;
  frames = [];
  frameIndex = -1;
  violationIndices = [];
  lastRunHadError = false;

  var workerSrc = `
self.onmessage = function(ev) {
  const code = ev.data.code;
  const initial = ev.data.array;
  let data = initial.slice();
  const p = 0, r = data.length - 1;
  let i = p - 1, j = p, x;
  const frames = [];
  const maxFrames = 700, maxOps = 3000;
  let ops = 0;
  function copyState(extra) {
    const s = { A: data.slice(), p, r, i, j, x, finalPivot: false };
    if (extra) Object.assign(s, extra);
    return s;
  }
  function add(kind, indices, message, extra) {
    ops++;
    if (ops > maxOps) throw new Error('Operation cap hit: possible infinite loop.');
    if (frames.length >= maxFrames) throw new Error('Frame cap hit: trace is too long.');
    frames.push({ kind, state: copyState(extra), indices: indices || [], message: String(message || kind) });
  }
  function checkIndex(idx) {
    if (!Number.isInteger(idx) || idx < p || idx > r) throw new Error('Index out of range: ' + idx);
  }
  self.pivot = function(idx) {
    checkIndex(idx);
    x = data[idx];
    add('pivot', [idx], 'pivot(' + idx + ') sets x = A[' + idx + '] = ' + x);
    return x;
  };
  self.compare = function(idx, val) {
    checkIndex(idx);
    const res = data[idx] <= val;
    add('compare', [idx, r], 'compare A[' + idx + ']=' + data[idx] + ' with x=' + val + ' → ' + res);
    return res;
  };
  self.swap = function(a, b) {
    checkIndex(a); checkIndex(b);
    const beforeA = data[a], beforeB = data[b];
    const t = data[a]; data[a] = data[b]; data[b] = t;
    add('swap', [a, b], 'swap A[' + a + ']=' + beforeA + ' with A[' + b + ']=' + beforeB);
  };
  self.setI = function(v) {
    if (!Number.isInteger(v) || v < p - 1 || v > r) throw new Error('Invalid i boundary: ' + v);
    i = v;
    add('setI', [Math.max(p, Math.min(r, v))], 'move i boundary after index ' + v);
  };
  self.setJ = function(v) {
    if (!Number.isInteger(v) || v < p || v > r) throw new Error('Invalid j boundary: ' + v);
    j = v;
    add('setJ', [Math.max(p, Math.min(r, v))], 'move j boundary to index ' + v);
  };
  self.note = function(text) {
    add('note', [], text || '');
  };
  Object.freeze(self.pivot); Object.freeze(self.compare); Object.freeze(self.swap);
  Object.freeze(self.setI); Object.freeze(self.setJ); Object.freeze(self.note);

  try {
    const fn = (new Function(code + '\\n; return (typeof PARTITION === "function") ? PARTITION : null;'))();
    if (typeof fn !== 'function') throw new Error('Missing entry point: define function PARTITION(A, p, r).');
    const readonlyA = new Proxy({}, {
      get(target, prop) {
        if (prop === 'length') return data.length;
        if (prop === Symbol.iterator) return data[Symbol.iterator].bind(data);
        if (String(Number(prop)) === String(prop)) return data[Number(prop)];
        return undefined;
      },
      set() { throw new Error('Do not mutate A directly; use swap(i, j).'); }
    });
    const ret = fn(readonlyA, p, r);
    const rv = (ret === undefined) ? 'undefined' : ret;
    frames.push({ kind: 'return', state: Object.assign(copyState({ returnValue: rv, finalPivot: Number.isInteger(ret) && data[ret] === x }), { returnValue: rv }), indices: Number.isInteger(ret) ? [ret] : [], message: 'return ' + rv });
    self.postMessage({ ok: true, frames });
  } catch (err) {
    frames.push({ kind: 'error', state: copyState({ error: String(err && err.message ? err.message : err) }), indices: [], message: 'Error: ' + String(err && err.message ? err.message : err) });
    self.postMessage({ ok: false, frames, error: String(err && err.message ? err.message : err) });
  }
};`;

  var blob = new Blob([workerSrc], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var settled = false;
  var timeout = setTimeout(function () {
    if (settled) return;
    settled = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    lastRunHadError = true;
    frames = [{
      kind: 'error',
      state: { A: inputArray.slice(), p: 0, r: inputArray.length - 1, i: -1, j: 0, x: inputArray[inputArray.length - 1] },
      indices: [],
      message: 'Error: execution timed out; check for an infinite loop.'
    }];
    status.textContent = 'error: timed out';
    runBtn.disabled = false;
    showFrame(0);
  }, 1800);

  worker.onmessage = function (ev) {
    if (settled) return;
    settled = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = ev.data.frames || [];
    lastRunHadError = !ev.data.ok;
    var correct = !lastRunHadError && checkSuccess(frames[frames.length - 1], inputArray);
    if (lastRunHadError) status.textContent = 'error';
    else if (correct) status.textContent = 'correct: partition property holds';
    else status.textContent = 'wrong answer: red cells violate the partition property';
    runBtn.disabled = false;
    showFrame(0);
  };

  worker.onerror = function (e) {
    if (settled) return;
    settled = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    lastRunHadError = true;
    frames = [{
      kind: 'error',
      state: { A: inputArray.slice(), p: 0, r: inputArray.length - 1, i: -1, j: 0, x: inputArray[inputArray.length - 1] },
      indices: [],
      message: 'Error: ' + (e.message || 'worker failed')
    }];
    status.textContent = 'error';
    runBtn.disabled = false;
    showFrame(0);
  };

  worker.postMessage({ code: document.getElementById('partitionCodeCode').value, array: inputArray });
}

function update_invariantCheckpoint(v) {
  stopPlay();
  frames = [];
  frameIndex = -1;
  checkpoint = v;
  renderFrame(frameFromDemo());
  document.getElementById('frameCaption').textContent = frameFromDemo().message;
}

function toggle_currentCase(on) {
  stopPlay();
  frames = [];
  frameIndex = -1;
  currentSmallCase = !!on;
  document.getElementById('currentCaseVal').textContent = on ? 'A[j] ≤ x' : 'A[j] > x';
  renderFrame(frameFromDemo());
  document.getElementById('frameCaption').textContent = frameFromDemo().message;
}

function applyDemoStep() {
  var st = demoSteps[demoIndex];
  checkpoint = st.checkpoint;
  currentSmallCase = st.small;
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
  document.getElementById('invariantCheckpointInput').value = st.checkpoint;
  document.getElementById('currentCaseInput').checked = st.small;
  document.getElementById('currentCaseVal').textContent = st.small ? 'A[j] ≤ x' : 'A[j] > x';
  stopPlay();
  frames = [];
  frameIndex = -1;
  var fr = frameFromDemo();
  renderFrame(fr);
  document.getElementById('frameCaption').textContent = fr.message;
  document.getElementById('partitionLog').textContent = st.title;
}

function prevStep() {
  demoIndex = (demoIndex + demoSteps.length - 1) % demoSteps.length;
  applyDemoStep();
}
function nextStep() {
  demoIndex = (demoIndex + 1) % demoSteps.length;
  applyDemoStep();
}

renderFrame(defaultAbstractFrame());
applyDemoStep();
window.__markRendered();
// @FIGURE_CODE_END

