      message: 'Error: execution timed out; check for an infinite loop.'
    }];
    status.textContent = 'error: timed out';
    runBtn.disabled = false;
    showFrame(0);
  }, 1800);

  worker.onmessage = function (ev) {
    if (settled) return;
    settled = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = ev.data.frames || [];
    lastRunHadError = !ev.data.ok;
    var correct = !lastRunHadError && checkSuccess(frames[frames.length - 1], inputArray);
    if (lastRunHadError) status.textContent = 'error';
    else if (correct) status.textContent = 'correct: partition property holds';
    else status.textContent = 'wrong answer: red cells violate the partition property';
