      "sample_code": "function PARTITION(A, p, r) {\n  const x = pivot(r);\n  let i = p - 1;\n  setI(i);\n\n  for (let j = p; j <= r - 1; j++) {\n    setJ(j);\n    note('Before the test, A[p..i] <= x, A[i+1..j-1] > x, and A[j..r-1] is unrestricted.');\n\n    if (compare(j, x)) {\n      i = i + 1;\n      swap(i, j);\n      setI(i);\n      note('A[j] belongs in the <= x region, so expand that region and swap it in.');\n    } else {\n      note('A[j] belongs in the > x region, so leave it where it is.');\n    }\n  }\n\n  swap(i + 1, r);\n  setI(i + 1);\n  note('The pivot is placed between the final <= x and > x regions.');\n  return i + 1;\n}",
