// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 1500, VH = 320;
draw.viewbox(0, 0, VW, VH);
draw.attr({ preserveAspectRatio: 'xMidYMid meet' });

var scene = draw.group();
var frames = [];
var frameIndex = -1;
var playTimer = null;
var violationIndices = [];
var lastRunHadError = false;
var viewMode = 'diagram';
var demoIndex = 0;

var sampleCode = document.getElementById('partitionCodeCode').value;
var buggyCode = "function PARTITION(A, p, r) {\n  const x = pivot(r);\n  let i = p - 1;\n  setI(i);\n\n  for (let j = p; j <= r - 1; j++) {\n    setJ(j);\n    if (compare(j, x)) {\n      swap(i, j);\n      setI(i);\n      i = i + 1;\n      note('Bug: swaps before advancing i, so the new <= x element is placed at the wrong boundary.');\n    }\n  }\n\n  swap(i + 1, r);\n  setI(i + 1);\n  return i + 1;\n}";
var starterCode = "function PARTITION(A, p, r) {\n  const x = pivot(r);\n  let i = p - 1;\n  setI(i);\n\n  for (let j = p; j <= r - 1; j++) {\n    setJ(j);\n    // TODO: compare A[j] with x.\n    // If it is <= x, advance i and swap it left.\n  }\n\n  // TODO: put the pivot in its final position.\n  return i + 1;\n}";

var demoSteps = [
  {
    title: 'Static invariant diagram',
    narration: 'The default view is the source-faithful abstract array: no numeric contents are shown except the pivot x, and the braces identify the three regions already classified or not yet examined.',
    mode: 'diagram'
  },
  {
    title: 'Optional execution trace',
    narration: 'Switching to the workbench adds concrete values and replay highlights so the learner can see how each comparison and swap preserves the same invariant.',
    mode: 'workbench'
  }
];

function withTip(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
  return el;
}

function addText(g, txt, x, y, size, anchor, italic, family) {
  return g.text(txt).font({
    family: family || 'Times New Roman, Times, serif',
    size: size,
    anchor: anchor || 'middle',
    style: italic ? 'italic' : 'normal'
  }).attr({
    x: x,
    y: y,
    'dominant-baseline': 'middle',
    fill: '#000',
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 4.5,
    'stroke-linejoin': 'round'
  });
}

function underBracePath(x1, x2, y) {
  var mid = (x1 + x2) / 2;
  var span = x2 - x1;
  var hook = Math.min(68, span * 0.17);
  var dip = 27;
  var cusp = 39;
  return 'M ' + x1 + ' ' + y +
    ' C ' + (x1 + 7) + ' ' + (y + 14) + ' ' + (x1 + hook * 0.55) + ' ' + (y + 18) + ' ' + (x1 + hook) + ' ' + (y + 19) +
    ' C ' + (mid - span * 0.18) + ' ' + (y + 20) + ' ' + (mid - 30) + ' ' + (y + 20) + ' ' + (mid - 10) + ' ' + (y + dip) +
    ' C ' + (mid - 4) + ' ' + (y + 30) + ' ' + (mid - 4) + ' ' + (y + cusp - 5) + ' ' + mid + ' ' + (y + cusp) +
    ' C ' + (mid + 4) + ' ' + (y + cusp - 5) + ' ' + (mid + 4) + ' ' + (y + 30) + ' ' + (mid + 10) + ' ' + (y + dip) +
    ' C ' + (mid + 30) + ' ' + (y + 20) + ' ' + (mid + span * 0.18) + ' ' + (y + 20) + ' ' + (x2 - hook) + ' ' + (y + 19) +
    ' C ' + (x2 - hook * 0.55) + ' ' + (y + 18) + ' ' + (x2 - 7) + ' ' + (y + 14) + ' ' + x2 + ' ' + y;
}

function drawBrace(g, x1, x2, y, label, tip, labelSize, italic) {
  if (x2 <= x1 + 18) return;
  var b = g.path(underBracePath(x1, x2, y)).fill('none').stroke({ color: '#000', width: 2.4, linecap: 'round', linejoin: 'round' });
  withTip(b, tip, label, tip);
  addText(g, label, (x1 + x2) / 2, y + 68, labelSize || 50, 'middle', italic !== false);
}

function abstractFrame() {
  return {
    kind: 'static',
    state: { A: null, n: 16, p: 0, i: 3, j: 10, r: 15, x: 'x' },
    indices: [],
    message: ''
  };
}

function initialWorkbenchFrame() {
  var A;
  try { A = parseArrayInput(); } catch (e) { A = [2, 8, 7, 1, 3, 5, 6, 4]; }
  return {
    kind: 'initial',
    state: { A: A, p: 0, r: A.length - 1, i: -1, j: 0, x: A[A.length - 1] },
    indices: [],
    message: 'Initial workbench state: A[r] will be used as pivot x.'
  };
}

function regionTip(k, s, finalPivot, q) {
  var i = s.i, j = s.j, r = s.r;
  if (finalPivot) {
    if (k < q) return 'Final left region: every value here is ≤ x.';
    if (k === q) return 'Pivot x is in its final partition position.';
    if (k > q) return 'Final right region: every value here is > x.';
  }
  if (k <= i) return 'A[p..i]: values already known to be ≤ x.';
  if (k > i && k < j && k < r) return 'A[i+1..j−1]: values already known to be > x.';
  if (k >= j && k < r) return 'A[j..r−1]: unrestricted values not examined yet.';
  if (k === r) return 'A[r]: the pivot cell holding x.';
  return 'Array cell in A[p..r].';
}

function renderFrame(frame, bad) {
  scene.clear();
  bad = bad || [];
  var s = frame && frame.state ? frame.state : abstractFrame().state;
  var A = Array.isArray(s.A) ? s.A.slice() : null;
  var n = A ? A.length : 16;
  var p = s.p == null ? 0 : s.p;
  var r = s.r == null ? n - 1 : s.r;
  var i = s.i == null ? 3 : s.i;
  var j = s.j == null ? 10 : s.j;
  var finalPivot = !!s.finalPivot;
  var q = finalPivot && Number.isInteger(Number(s.returnValue)) ? Number(s.returnValue) : i;

  var left = 21;
  var top = viewMode === 'diagram' ? 88 : 105;
  var totalW = 1458;
  var h = viewMode === 'diagram' ? 90 : 76;
  var cw = totalW / n;
  var light = '#e6e6e6';
  var dark = '#9c9c9c';

  var bg = scene.rect(totalW, h).move(left, top).fill('#fff').stroke({ color: '#000', width: 2.4 });
  withTip(bg, 'The subarray A[p..r] currently being partitioned.', 'Subarray A[p..r]', 'PARTITION rearranges this one subarray around the pivot. The invariant describes what is known about each contiguous region.');

  for (var k = 0; k < n; k++) {
    var fill = '#fff';
    if (finalPivot) {
      if (k < q) fill = light;
      else if (k > q) fill = dark;
    } else {
      if (k <= i) fill = light;
      else if (k > i && k < j && k < r) fill = dark;
    }
    if (!A && k === r) fill = '#fff';

    var cell = scene.rect(cw, h).move(left + k * cw, top).fill(fill).stroke({ color: '#000', width: 2 });
    withTip(cell, regionTip(k, { i: i, j: j, r: r }, finalPivot, q), 'Partition invariant region', regionTip(k, { i: i, j: j, r: r }, finalPivot, q));

    if (A) {
      addText(scene, String(A[k]), left + k * cw + cw / 2, top + h / 2 + 1, Math.min(34, cw * 0.36), 'middle', false);
    }
  }

  for (var grid = 1; grid < n; grid++) {
    scene.line(left + grid * cw, top, left + grid * cw, top + h).stroke({ color: '#000', width: 2 });
  }

  if (!A) {
    addText(scene, 'x', left + r * cw + cw / 2, top + h / 2 + 3, 59, 'middle', true);
  } else if (s.x !== undefined) {
    addText(scene, 'x=' + String(s.x), left + r * cw + cw / 2, top + h + 26, 18, 'middle', false, 'sans-serif');
  }

  function thickBoundary(boundary, label, tip, labelX, labelY) {
    var x = left + boundary * cw;
    var w = viewMode === 'diagram' ? 20 : 14;
    var rect = scene.rect(w, h + 22).move(x - w / 2, top - 11).fill('#000');
    withTip(rect, tip, label, tip);
    addText(scene, label, labelX == null ? x : labelX, labelY == null ? top - (viewMode === 'diagram' ? 50 : 32) : labelY, viewMode === 'diagram' ? 58 : 34, 'middle', true);
  }

  addText(scene, 'p', left + cw * 0.48, top - (viewMode === 'diagram' ? 50 : 32), viewMode === 'diagram' ? 58 : 34, 'middle', true);

  if (finalPivot) {
    thickBoundary(Math.max(0, Math.min(n, q)), 'i', 'i marks the final pivot boundary after the last swap.');
    thickBoundary(Math.max(0, Math.min(n - 1, r)), 'j', 'At the end of the scan, the unrestricted region is gone.');
    thickBoundary(r, 'r', 'r was the original pivot position.');
  } else {
    thickBoundary(Math.max(0, Math.min(n, i + 1)), 'i', 'i is the boundary after the ≤ x region: A[p..i].');
    thickBoundary(Math.max(0, Math.min(n, j)), 'j', 'j is the boundary before the unrestricted region: A[j..r−1].');
    thickBoundary(Math.max(0, Math.min(n, r)), 'r', 'r marks the boundary before the pivot cell A[r].');
  }

  var idxs = (frame && frame.indices) ? frame.indices.slice() : [];
  idxs = idxs.concat(bad || []);
  var seen = {};
  idxs.forEach(function (idx) {
    idx = Number(idx);
    if (!Number.isInteger(idx) || idx < 0 || idx >= n || seen[idx]) return;
    seen[idx] = true;
    var isBad = bad.indexOf(idx) >= 0;
    var color = isBad ? '#d62728' : (frame.kind === 'swap' ? '#ff9800' : '#2b78e4');
    scene.rect(Math.max(4, cw - 10), h - 10).move(left + idx * cw + 5, top + 5)
      .fill('none').stroke({ color: color, width: viewMode === 'diagram' ? 0 : 4 }).radius(2);
  });

  if (viewMode === 'workbench' && frame && frame.kind === 'swap' && idxs.length >= 2) {
    var a = Number(idxs[0]), b = Number(idxs[1]);
    if (Number.isInteger(a) && Number.isInteger(b) && a >= 0 && b >= 0 && a < n && b < n && a !== b) {
      var x1 = left + a * cw + cw / 2, x2 = left + b * cw + cw / 2, y = top - 18;
      scene.path('M ' + x1 + ' ' + y + ' C ' + x1 + ' ' + (y - 46) + ' ' + x2 + ' ' + (y - 46) + ' ' + x2 + ' ' + y)
        .fill('none').stroke({ color: '#ff9800', width: 3.2, linecap: 'round' });
      scene.circle(9).center(x1, y).fill('#ff9800');
      scene.circle(9).center(x2, y).fill('#ff9800');
    }
  }

  var braceY = top + h + (viewMode === 'diagram' ? 24 : 18);
  if (finalPivot) {
    drawBrace(scene, left, left + Math.max(0, q) * cw, braceY, '≤ x', 'All values left of the pivot are ≤ x.', viewMode === 'diagram' ? 50 : 28, true);
    drawBrace(scene, left + Math.min(n, q + 1) * cw, left + (r + 1) * cw, braceY, '> x', 'All values right of the pivot are > x.', viewMode === 'diagram' ? 50 : 28, true);
  } else {
    drawBrace(scene, left, left + Math.max(0, i + 1) * cw, braceY, '≤ x', 'A[p..i] is already known to contain values ≤ x.', viewMode === 'diagram' ? 54 : 28, true);
    drawBrace(scene, left + Math.max(0, i + 1) * cw, left + Math.max(0, Math.min(j, r)) * cw, braceY, '> x', 'A[i+1..j−1] is already known to contain values > x.', viewMode === 'diagram' ? 54 : 28, true);
    drawBrace(scene, left + Math.max(0, Math.min(j, r)) * cw, left + r * cw, braceY, 'unrestricted', 'A[j..r−1] has not been examined yet.', viewMode === 'diagram' ? 52 : 28, false);
  }

  if (viewMode === 'workbench') {
    var msg = frame && frame.message ? frame.message : 'Workbench mode: run or replay code to see the invariant maintained.';
    scene.rect(1130, 30).move(185, 22).fill({ color: '#fff', opacity: 0.88 }).stroke({ color: '#d8d8d8', width: 1 });
    scene.text(msg).font({ family: 'sans-serif', size: 15, anchor: 'middle' })
      .attr({ x: 750, y: 41, 'dominant-baseline': 'middle', fill: '#222' });
  }
}

function renderCurrent() {
  if (viewMode === 'diagram') renderFrame(abstractFrame());
  else if (frames.length && frameIndex >= 0) renderFrame(frames[frameIndex], frameIndex === frames.length - 1 ? violationIndices : []);
  else renderFrame(initialWorkbenchFrame());
}

function parseArrayInput() {
  var src = document.getElementById('partitionCodeInput').value.trim();
  if (!src) throw new Error('Enter at least one number.');
  var vals = src.split(/[,\s]+/).filter(Boolean).map(function (s) { return Number(s); });
  if (!vals.length || vals.some(function (v) { return !isFinite(v); })) throw new Error('Array input must be a comma-separated list of numbers.');
  if (vals.length < 2) throw new Error('Need at least two elements so A[r] can be the pivot.');
  if (vals.length > 16) throw new Error('Use at most 16 elements for a readable trace.');
  return vals;
}

function loadPartitionSample(which) {
  document.getElementById('partitionCodeCode').value = which === 'buggy' ? buggyCode : (which === 'starter' ? starterCode : sampleCode);
}

function setViewMode(mode) {
  viewMode = mode === 'workbench' ? 'workbench' : 'diagram';
  document.getElementById('viewModeInput').checked = viewMode === 'workbench';
  document.getElementById('workbenchControls').style.display = viewMode === 'workbench' ? 'flex' : 'none';
  stopPlay();
  renderCurrent();
}

function toggle_viewMode(on) {
  setViewMode(on ? 'workbench' : 'diagram');
  demoIndex = on ? 1 : 0;
  document.getElementById('demoNarration').textContent = demoSteps[demoIndex].narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
}

function applyDemoStep() {
  var st = demoSteps[demoIndex];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
  setViewMode(st.mode);
}

function prevStep() {
  demoIndex = (demoIndex + demoSteps.length - 1) % demoSteps.length;
  applyDemoStep();
}

function nextStep() {
  demoIndex = (demoIndex + 1) % demoSteps.length;
  applyDemoStep();
}

function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  var btn = document.getElementById('playBtn');
  if (btn) btn.textContent = '▶';
}

function updateCounterAndCaption() {
  var counter = document.getElementById('frameCounter');
  var cap = document.getElementById('frameCaption');
  var logEl = document.getElementById('partitionLog');
  if (!frames.length || frameIndex < 0) {
    counter.textContent = '0 of 0';
    cap.textContent = 'Run code to generate a replay.';
    logEl.textContent = '';
    return;
  }
  counter.textContent = (frameIndex + 1) + ' of ' + frames.length;
  cap.textContent = frames[frameIndex].message || frames[frameIndex].kind;
  var start = Math.max(0, frameIndex - 8);
  logEl.textContent = frames.slice(start, frameIndex + 1).map(function (f, k) {
    return (start + k + 1) + '. ' + (f.message || f.kind);
  }).join('\n');
}

function showFrame(idx) {
  if (!frames.length) return;
  frameIndex = Math.max(0, Math.min(frames.length - 1, idx));
  if (viewMode !== 'workbench') setViewMode('workbench');
  renderFrame(frames[frameIndex], frameIndex === frames.length - 1 ? violationIndices : []);
  updateCounterAndCaption();
}

function firstFrame() { stopPlay(); showFrame(0); }
function prevFrame() { stopPlay(); showFrame(frameIndex - 1); }

function nextFrame() {
  if (!frames.length) return;
  if (frameIndex >= frames.length - 1) { stopPlay(); return; }
  showFrame(frameIndex + 1);
}

function togglePlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = '❚❚';
  playTimer = setInterval(function () {
    if (frameIndex >= frames.length - 1) stopPlay();
    else showFrame(frameIndex + 1);
  }, 650 / Number(document.getElementById('partitionSpeedInput').value || 1));
}

function checkSuccess(finalFrame, original) {
  violationIndices = [];
  if (!finalFrame || !finalFrame.state || lastRunHadError) return false;
  var A = finalFrame.state.A || [];
  var q = Number(finalFrame.state.returnValue);
  var x = original[original.length - 1];
  var ok = Number.isInteger(q) && q >= 0 && q < A.length && A[q] === x;
  if (!Number.isInteger(q) || q < 0 || q >= A.length) {
    for (var z = 0; z < A.length; z++) violationIndices.push(z);
    return false;
  }
  if (A[q] !== x) violationIndices.push(q);
  for (var a = 0; a < q; a++) if (!(A[a] <= x)) { ok = false; violationIndices.push(a); }
  for (var b = q + 1; b < A.length; b++) if (!(A[b] > x)) { ok = false; violationIndices.push(b); }
  return ok && violationIndices.length === 0;
}

function runPartitionCode() {
  stopPlay();
  setViewMode('workbench');
  var status = document.getElementById('partitionStatus');
  var runBtn = document.getElementById('partitionRunBtn');
  var inputArray;
  try {
    inputArray = parseArrayInput();
  } catch (e) {
    status.textContent = 'error: ' + e.message;
    return;
  }

  status.textContent = 'running…';
  runBtn.disabled = true;
  frames = [];
  frameIndex = -1;
  violationIndices = [];
  lastRunHadError = false;
  updateCounterAndCaption();

  var workerSrc = `
self.onmessage = function(ev) {
  const code = ev.data.code;
  const initial = ev.data.array;
  let data = initial.slice();
  const p = 0, r = data.length - 1;
  let i = p - 1, j = p, x = undefined;
  const frames = [];
  const maxFrames = 700, maxOps = 3000;
  let ops = 0;

  function copyState(extra) {
    const s = { A: data.slice(), p, r, i, j, x, finalPivot: false };
    if (extra) Object.assign(s, extra);
    return s;
  }
  function add(kind, indices, message, extra) {
    ops++;
    if (ops > maxOps) throw new Error('Operation cap hit: possible infinite loop.');
    if (frames.length >= maxFrames) throw new Error('Frame cap hit: trace is too long.');
    frames.push({ kind, state: copyState(extra), indices: (indices || []).slice(), message: String(message || kind) });
  }
  function checkIndex(idx) {
    if (!Number.isInteger(idx) || idx < p || idx > r) throw new Error('Index out of range: ' + idx);
  }

  function pivotOp(idx) {
    checkIndex(idx);
    x = data[idx];
    add('pivot', [idx], 'pivot(' + idx + ') sets x = A[' + idx + '] = ' + x);
    return x;
  }
  function compareOp(idx, val) {
    checkIndex(idx);
    const res = data[idx] <= val;
    add('compare', [idx, r], 'compare A[' + idx + ']=' + data[idx] + ' with x=' + val + ' → ' + res);
    return res;
  }
  function swapOp(a, b) {
    checkIndex(a); checkIndex(b);
    const beforeA = data[a], beforeB = data[b];
    const t = data[a]; data[a] = data[b]; data[b] = t;
    add('swap', [a, b], 'swap A[' + a + ']=' + beforeA + ' with A[' + b + ']=' + beforeB);
  }
  function setIOp(v) {
    if (!Number.isInteger(v) || v < p - 1 || v > r) throw new Error('Invalid i boundary: ' + v);
    i = v;
    add('setI', [Math.max(p, Math.min(r, v))], 'move i boundary after index ' + v);
  }
  function setJOp(v) {
    if (!Number.isInteger(v) || v < p || v > r) throw new Error('Invalid j boundary: ' + v);
    j = v;
    add('setJ', [Math.max(p, Math.min(r, v))], 'move j boundary to index ' + v);
  }
  function noteOp(text) {
    add('note', [], text || '');
  }

  const api = Object.freeze({ pivot: pivotOp, compare: compareOp, swap: swapOp, setI: setIOp, setJ: setJOp, note: noteOp });
  self.pivot = api.pivot;
  self.compare = api.compare;
  self.swap = api.swap;
  self.setI = api.setI;
  self.setJ = api.setJ;
  self.note = api.note;

  try {
    const fn = (new Function(code + '\\n; return (typeof PARTITION === "function") ? PARTITION : null;'))();
    if (typeof fn !== 'function') throw new Error('Missing entry point: define function PARTITION(A, p, r).');

    const readonlyA = new Proxy({}, {
      get(target, prop) {
        if (prop === 'length') return data.length;
        if (prop === Symbol.iterator) return data[Symbol.iterator].bind(data);
        const n = Number(prop);
        if (Number.isInteger(n)) return data[n];
        return undefined;
      },
      set() { throw new Error('Do not mutate A directly; use swap(i, j).'); },
      defineProperty() { throw new Error('Do not mutate A directly; use swap(i, j).'); },
      deleteProperty() { throw new Error('Do not mutate A directly; use swap(i, j).'); }
    });

    const ret = fn(readonlyA, p, r);
    frames.push({
      kind: 'return',
      state: copyState({ returnValue: ret, finalPivot: Number.isInteger(ret) && data[ret] === x }),
      indices: Number.isInteger(ret) ? [ret] : [],
      message: 'return ' + String(ret)
    });
    self.postMessage({ ok: true, frames });
  } catch (err) {
    frames.push({
      kind: 'error',
      state: copyState({ error: String(err && err.message ? err.message : err) }),
      indices: [],
      message: 'Error: ' + String(err && err.message ? err.message : err)
    });
    self.postMessage({ ok: false, frames, error: String(err && err.message ? err.message : err) });
  }
};`;

  var blob = new Blob([workerSrc], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var settled = false;

  var timeout = setTimeout(function () {
    if (settled) return;
    settled = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    lastRunHadError = true;
    frames = [{
      kind: 'error',
      state: { A: inputArray.slice(), p: 0, r: inputArray.length - 1, i: -1, j: 0, x: inputArray[inputArray.length - 1] },
      indices: [],
      message: 'Error: execution timed out; check for an infinite loop.'
    }];
    status.textContent = 'error: timed out';
    runBtn.disabled = false;
    showFrame(0);
  }, 1800);

  worker.onmessage = function (ev) {
    if (settled) return;
    settled = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);

    frames = ev.data.frames || [];
    lastRunHadError = !ev.data.ok;
    var correct = !lastRunHadError && checkSuccess(frames[frames.length - 1], inputArray);

    if (lastRunHadError) status.textContent = 'error: see final frame';
    else if (correct) status.textContent = 'correct: partition property holds';
    else status.textContent = 'wrong answer: red cells violate the partition property';

    runBtn.disabled = false;
    showFrame(0);
  };

  worker.onerror = function (e) {
    if (settled) return;
    settled = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    lastRunHadError = true;
    frames = [{
      kind: 'error',
      state: { A: inputArray.slice(), p: 0, r: inputArray.length - 1, i: -1, j: 0, x: inputArray[inputArray.length - 1] },
      indices: [],
      message: 'Error: ' + (e.message || 'worker failed')
    }];
    status.textContent = 'error: worker failed';
    runBtn.disabled = false;
    showFrame(0);
  };

  worker.postMessage({ code: document.getElementById('partitionCodeCode').value, array: inputArray });
}

applyDemoStep();
updateCounterAndCaption();
window.__markRendered();
